public sealed class SqsPoller(IAmazonSQS sqs)
{
    // BAD: blocks a pool thread for the entire SQS wait
    public Message ReceiveBlocking(string queueUrl)
    {
        var response = sqs.ReceiveMessageAsync(queueUrl)
            .GetAwaiter().GetResult();
        return response.Messages[0];
    }

    // GOOD: releases the thread while waiting
    public async Task<Message?> ReceiveAsync(
        string queueUrl, CancellationToken cancellationToken)
    {
        var response = await sqs.ReceiveMessageAsync(queueUrl, cancellationToken);
        return response.Messages.Count > 0 ? response.Messages[0] : null;
    }
}

public async Task<SessionData> LoadSessionAsync(
    string sessionId, CancellationToken cancellationToken)
{
    // Start both — do not await yet
    var redisTask = _redis.StringGetAsync(sessionId);
    var httpTask = _http.GetStringAsync($"/auth/{sessionId}", cancellationToken);

    // Wait for both concurrently on one thread
    await Task.WhenAll(redisTask, httpTask);

    return new SessionData(redisTask.Result.ToString(), httpTask.Result);
}

// WRONG: still pays a thread for the entire blocking wait
var message = await Task.Run(() =>
    sqs.ReceiveMessage(queueUrl)); // synchronous SDK call

// RIGHT: use the truly async API
var message = await sqs.ReceiveMessageAsync(queueUrl, cancellationToken);
